document.addEventListener('keydown', event => { const map = { a: 'left', ArrowLeft: 'left', d: 'right', ArrowRight: 'right', w: 'up', ArrowUp: 'up', s: 'down', ArrowDown: 'down' }; if (map[event.key]) { event.preventDefault(); doAction(map[event.key]); } if (event.key === 'Escape' && mode === 'playing' && collisionPause === 0 && rewindTime === 0) setMode('paused'); }); document.addEventListener('pointerdown', event => { if (event.isPrimary && event.pointerType !== 'mouse') swipeStart = { x: event.clientX, y: event.clientY }; }); document.addEventListener('pointerup', event => { if (!swipeStart || !event.isPrimary) return; const dx = event.clientX - swipeStart.x; const dy = event.clientY - swipeStart.y; swipeStart = null; if (Math.max(Math.abs(dx), Math.abs(dy)) < CONFIG.swipeThreshold) return; doAction(Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? 'left' : 'right') : (dy < 0 ? 'up' : 'down')); }); document.addEventListener('pointercancel', () => { swipeStart = null; }); document.querySelectorAll('[data-action]').forEach(button => button.addEventListener('pointerdown', event => { event.preventDefault(); doAction(button.dataset.action); }));
