    action(input) { doAction(input); return testSnapshot(); },
    placeInLane(nextLane = 1) { const next = Math.max(0, Math.min(2, Math.round(Number(nextLane) || 0))); lane = targetLane = next; girl.position.x = laneX(next - 1); return testSnapshot(); },
    step(seconds = .05, render = true) {
      const dt = Math.max(0, Math.min(.25, Number(seconds) || 0));
      if (mode === 'playing') { if (collisionPause === 0 && rewindTime === 0) updateAi(dt); updateGame(dt); }
      if (render) { camera.lookAt(0, 1.7, -10); renderer.render(scene, camera); } return testSnapshot();
    },
    advance(seconds = .05) { const total = Math.max(0, Number(seconds) || 0); const steps = Math.ceil(total / .05); for (let index = 0; index < steps; index++) this.step(Math.min(.05, total - index * .05), false); camera.lookAt(0, 1.7, -10); renderer.render(scene, camera); return testSnapshot(); },
    seekDistance(distance = 0) { elapsed = Math.max(0, Number(distance) || 0) / (CONFIG.speed * speedMultiplier()); action = null; actionTime = 0; collisionPause = 0; rewindTime = 0; syncWorldToElapsed(); updateHUD(); camera.lookAt(0, 1.7, -10); renderer.render(scene, camera); return testSnapshot(); },
    snapshot: testSnapshot,
    levels: LEVELS.map(level => ({ name: level.name, duration: level.duration, finishDistance: level.finishDistance, speedMultiplier: level.speedMultiplier, obstacles: level.obstacles.map(spec => ({ ...spec })) })),
    debug: DEBUG_CONFIG
