function makeSakuraTree(side, z, index) { const tree = new THREE.Group(); tree.add(box('sakura trunk', [.7, 4.2, .7], COLORS.wood, [0, 1.55, 0])); const blossomColors = [0xff9fbd, 0xf47aa3, 0xffbfd2, 0xe96591, 0xffd1df]; const crown = new THREE.Mesh(new THREE.DodecahedronGeometry(2.4, 0), mat(blossomColors[index % blossomColors.length])); crown.position.y = 5.3; tree.add(crown); tree.position.set(side * 18, 0, z); world.add(tree); treeMeshes.push({ tree, baseZ: z }); }
