function makeMountFuji() { const fuji = new THREE.Group(); fuji.name = 'Mount Fuji landmark'; const foothills = new THREE.Mesh(new THREE.ConeGeometry(34, 16, 7), new THREE.MeshBasicMaterial({ color: 0x315d82, fog: false })); foothills.position.set(0, 8, 0); fuji.add(foothills); const mountain = new THREE.Mesh(new THREE.ConeGeometry(39, 30, 7), new THREE.MeshBasicMaterial({ color: 0x477ba0, fog: false })); mountain.position.set(0, 15, .2); fuji.add(mountain); const snowShape = new THREE.Shape(); snowShape.moveTo(-15, 17); snowShape.lineTo(15, 17); snowShape.lineTo(0, 30); snowShape.closePath(); const snowField = new THREE.Mesh(new THREE.ShapeGeometry(snowShape), new THREE.MeshBasicMaterial({ color: 0xf7f8f2, side: THREE.DoubleSide, fog: false, depthTest: false, depthWrite: false })); snowField.position.z = 9; snowField.renderOrder = 10; fuji.add(snowField); const facetColors = [0xd7e5ef, 0xe5edf3, 0xcbdce9]; [[-5.5, 18.2, -2.2], [0, 19.2, 0], [5.5, 18.2, 2.2]].forEach(([x, y, zOffset], index) => { const facetShape = new THREE.Shape(); facetShape.moveTo(x - 1.8, y); facetShape.lineTo(x + 1.8, y + .5); facetShape.lineTo(0, 28.6); facetShape.closePath(); const facet = new THREE.Mesh(new THREE.ShapeGeometry(facetShape), new THREE.MeshBasicMaterial({ color: facetColors[index], side: THREE.DoubleSide, fog: false, depthTest: false, depthWrite: false })); facet.position.z = 9.05 + zOffset; facet.renderOrder = 11; fuji.add(facet); }); fuji.position.set(2, -3, -135); skyDecor.add(fuji); }
function makeTokyoPetals() { for (let index = 0; index < 44; index += 1) { const material = new THREE.MeshBasicMaterial({ color: [0xffc3d8, 0xf58bb1, 0xffa7c7][index % 3], transparent: true, opacity: .78, side: THREE.DoubleSide }); const petal = new THREE.Mesh(new THREE.PlaneGeometry(.16 + (index % 3) * .035, .24 + (index % 2) * .04), material); petal.rotation.set(.15, index * .7, index * .41); const side = index % 2 ? 1 : -1; petal.userData = { startX: side * (12 + ((index * 17) % 40) / 10), baseY: 3.2 + ((index * 19) % 65) / 10, baseZ: -12 - ((index * 29) % 118), windSpeed: 2.8 + (index % 5) * .55, windWidth: 30 + (index % 3) * 3, driftY: .16 + (index % 3) * .06, speed: .5 + (index % 5) * .12, phase: index * 1.73 }; world.add(petal); tokyoPetals.push(petal); } syncTokyoPetals(0); }
function syncTokyoPetals(elapsedTime) { tokyoPetals.forEach(petal => { const motion = petal.userData; const wrappedX = ((motion.startX + elapsedTime * motion.windSpeed + motion.windWidth) % (motion.windWidth * 2)) - motion.windWidth; petal.position.set(wrappedX + Math.sin(elapsedTime * motion.speed + motion.phase) * .35, motion.baseY + Math.sin(elapsedTime * motion.speed * .8 + motion.phase) * motion.driftY, motion.baseZ); petal.rotation.z = motion.phase + elapsedTime * motion.speed * .9; }); }
